import{_ as e,o as s,c as n,a4 as t}from"./chunks/framework.BUqnS5H7.js";const f=JSON.parse('{"title":"RecordBatch v2 格式","description":"","frontmatter":{},"headers":[],"relativePath":"kafka/reference/chapter-01-record-batch-format.md","filePath":"kafka/reference/chapter-01-record-batch-format.md"}'),r={name:"kafka/reference/chapter-01-record-batch-format.md"};function c(p,a,l,o,i,d){return s(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="recordbatch-v2-格式" tabindex="-1" data-src-line="1" data-src-file="kafka/reference/chapter-01-record-batch-format.md">RecordBatch v2 格式 <a class="header-anchor" href="#recordbatch-v2-格式" aria-label="Permalink to &quot;RecordBatch v2 格式&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="kafka/reference/chapter-01-record-batch-format.md"><p data-src-line="3" data-src-file="kafka/reference/chapter-01-record-batch-format.md">RecordBatch v2 是 Kafka 0.11+ 使用的消息格式（<a href="https://cwiki.apache.org/confluence/display/KAFKA/KIP-98" target="_blank" rel="noreferrer">KIP-98</a> 引入）。本文是字节级参考，面向需要深入底层的读者。</p></blockquote><h2 id="_1-批头结构" tabindex="-1" data-src-line="5" data-src-file="kafka/reference/chapter-01-record-batch-format.md">1. 批头结构 <a class="header-anchor" href="#_1-批头结构" aria-label="Permalink to &quot;1. 批头结构&quot;">​</a></h2><p data-src-line="7" data-src-file="kafka/reference/chapter-01-record-batch-format.md"><code>.log</code> 文件里不是「一条条消息」，而是「一批批 RecordBatch」。一批的头部固定 61 字节，后面跟变长 <code>Record[]</code>：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>偏移(字节)  长度  字段                       说明</span></span>
<span class="line"><span>  0        8    baseOffset                该批第一条消息的绝对 offset</span></span>
<span class="line"><span>  8        4    batchLength               从 partitionLeaderEpoch 到末尾的字节数</span></span>
<span class="line"><span> 12        4    partitionLeaderEpoch      KIP-101：Broker 收到时写入</span></span>
<span class="line"><span> 16        1    magic                     固定 2</span></span>
<span class="line"><span> 17        4    crc                       CRC-32C（Castagnoli）</span></span>
<span class="line"><span> 21        2    attributes                低 3 位=压缩算法（0 none/1 gzip/2 snappy/3 lz4/4 zstd）</span></span>
<span class="line"><span>                                          bit 3=timestampType, bit 4=isTransactional</span></span>
<span class="line"><span>                                          bit 5=isControlBatch, bit 6=hasDeleteHorizonMs</span></span>
<span class="line"><span> 23        4    lastOffsetDelta           该批最后一条相对 baseOffset 的偏移</span></span>
<span class="line"><span> 27        8    baseTimestamp             该批第一条时间戳</span></span>
<span class="line"><span> 35        8    maxTimestamp              该批最大时间戳</span></span>
<span class="line"><span> 43        8    producerId                KIP-98</span></span>
<span class="line"><span> 51        2    producerEpoch             KIP-98</span></span>
<span class="line"><span> 53        4    baseSequence              KIP-98</span></span>
<span class="line"><span> 57        4    recordCount               该批消息数</span></span>
<span class="line"><span> 61        …    records[]                 变长记录数组</span></span></code></pre></div><p data-src-line="29" data-src-file="kafka/reference/chapter-01-record-batch-format.md">CRC 覆盖 attributes 之后的所有字节。<code>partitionLeaderEpoch</code> 不参与 CRC 计算——它由 Broker 在收到 Produce 请求时才写入，若纳入 CRC 每次都要重算，代价过高。</p><h2 id="_2-批内-record-结构" tabindex="-1" data-src-line="31" data-src-file="kafka/reference/chapter-01-record-batch-format.md">2. 批内 Record 结构 <a class="header-anchor" href="#_2-批内-record-结构" aria-label="Permalink to &quot;2. 批内 Record 结构&quot;">​</a></h2><p data-src-line="33" data-src-file="kafka/reference/chapter-01-record-batch-format.md">每条 <code>Record</code> 使用 varint 编码，只存相对量：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>length          varint</span></span>
<span class="line"><span>attributes      int8    （目前未用）</span></span>
<span class="line"><span>timestampDelta  varlong  相对 baseTimestamp</span></span>
<span class="line"><span>offsetDelta    varint    相对 baseOffset</span></span>
<span class="line"><span>keyLength       varint</span></span>
<span class="line"><span>key             bytes</span></span>
<span class="line"><span>valueLength     varint</span></span>
<span class="line"><span>value           bytes</span></span>
<span class="line"><span>headers[]       Header 数组（KIP-82，0.11 引入）</span></span></code></pre></div><p data-src-line="47" data-src-file="kafka/reference/chapter-01-record-batch-format.md">同批内共享 producerId / baseTimestamp / baseOffset，每条只写增量，压缩比明显高于逐条独立编码。</p><h2 id="_3-源码参考" tabindex="-1" data-src-line="49" data-src-file="kafka/reference/chapter-01-record-batch-format.md">3. 源码参考 <a class="header-anchor" href="#_3-源码参考" aria-label="Permalink to &quot;3. 源码参考&quot;">​</a></h2><p data-src-line="51" data-src-file="kafka/reference/chapter-01-record-batch-format.md">字节偏移量在 <code>DefaultRecordBatch</code> 中以常量形式定义：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BASE_OFFSET_OFFSET = 0</span></span>
<span class="line"><span>LENGTH_OFFSET = 8</span></span>
<span class="line"><span>PARTITION_LEADER_EPOCH_OFFSET = 12</span></span>
<span class="line"><span>MAGIC_OFFSET = 16</span></span>
<span class="line"><span>CRC_OFFSET = 17</span></span>
<span class="line"><span>ATTRIBUTES_OFFSET = 21</span></span></code></pre></div><p data-src-line="62" data-src-file="kafka/reference/chapter-01-record-batch-format.md">来源：<a href="https://github.com/apache/kafka/blob/trunk/clients/src/main/java/org/apache/kafka/common/record/DefaultRecordBatch.java" target="_blank" rel="noreferrer">DefaultRecordBatch.java</a>、<a href="https://kafka.apache.org/37/implementation/message-format" target="_blank" rel="noreferrer">Kafka 官方 Message Format</a></p>`,14)])])}const m=e(r,[["render",c]]);export{f as __pageData,m as default};
